INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (71, 267, '10/12Microns thermal transfer BOPET film no corona treatment', '../upload/image/20180923/20180923113748_23897.jpg', '<p><span style="font-family:Tahoma;font-size:18px;color:#009900;">12Micro</span><span style="font-family:Tahoma;font-size:18px;color:#009900;">ns thermal transfer BOPET film no corona treatment</span><br/></p><p><b><span style="font-family:Tahoma;font-size:18px;color:#009900;">BOPET PLAIN FILM </span><br/> </b><span style="font-family:Tahoma;font-size:18px;color:#009900;">BOPET film (biaxially oriented Polyester films) featurines good thermal stability and tenacity; low air and water permeability; applicable to vacuum aluminum plating, compound package, cooking bag manufacture, etc. </span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">Featuring : </span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">Having the good adhesion with ink and coating, can be used for multi-color printings with good flatness. Is mainly used in heat-sealing bags of frozen food, industrial products and cosmetics packaging. </span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">Specification:</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">thickness: 12 microns-25 microns, 75 microns-150 microns ,185 microns-380 microns, 500 microns</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">width :200-1200MM </span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">length : 500m ,1000m ,1500m,4000m,6000m,9000m,12000m</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">Polyester film is wound around paper shaft with an internal diameter of 76.2mm-152.4mm and covered with polyethylene film; each coil is supported by damper and put in carton; medium and large package needs wooden mount.</span><br/> <span style="font-family:Tahoma;font-size:18px;color:#009900;">Customer''s own requirement is available for us such as printed OEM logos and private label or particular size and package style.</span></p> <p align="center"> <b><span style="font-family:Tahoma;font-size:18px;color:#009900;">Polyester Film Test Report </span></b><b></b></p> <div align="center"> <table border="1" cellpadding="0" cellspacing="0" width="671"> <tbody> <tr> <td colspan="3" width="122"> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">Film Item</span></p> </td> <td colspan="2" width="105"> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">BOPET</span></p> </td> <td width="90"> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">Date </span></p> </td> <td width="123"> <p></p> </td> <td width="84"> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">Quantity </span></p> </td> <td colspan="2" width="148"> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">2,841tons</span></p> </td> </tr> <tr> <td colspan="3" width="122"> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">Roll NO.</span></p> </td> <td colspan="2" width="105"> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">B--07121704</span></p> </td> <td width="90"> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">Test Date </span></p> </td> <td width="123"> <p align="center"></p> </td> <td colspan="2" width="119"> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">Temperature/Humidity</span></p> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">Condition</span></p> </td> <td width="112"> <p align="center"> <span style="font-size:18px;font-family:Tahoma;color:#009900;">23℃/50RH</span></p> </td> </tr> <tr> <td colspan="3" width="122"> <p align="center"> <span style="font-size:1